"""
Abstraction interfaces for reduced coupling.

These interfaces define minimal contracts for core dependencies,
enabling dependency injection and testability.
"""
from typing import Protocol, List, Optional

from .models import Coin, Pair


class DatabaseInterface(Protocol):
    """Interface for database operations."""

    def set_coins(self, symbols: List[str]) -> None:
        """Set the list of supported coins."""
        ...

    def get_coins(self, only_enabled: bool = True) -> List[Coin]:
        """Get all coins, optionally only enabled ones."""
        ...

    def get_coin(self, coin: Coin) -> Coin:
        """Get a specific coin."""
        ...

    def set_current_coin(self, coin: Coin) -> None:
        """Set the current coin being traded."""
        ...

    def get_current_coin(self) -> Optional[Coin]:
        """Get the current coin being traded."""
        ...

    def get_pairs_from(self, from_coin: Coin, only_enabled: bool = True) -> List[Pair]:
        """Get pairs where the given coin is the source."""
        ...

    def log_scout(
        self,
        pair: Pair,
        target_ratio: float,
        current_coin_price: float,
        other_coin_price: float,
    ) -> None:
        """Log a scouting event for a pair."""
        ...


class ConfigInterface(Protocol):
    """Interface for configuration access."""

    @property
    def BRIDGE(self) -> Coin:
        """Get the bridge coin."""
        ...

    @property
    def BRIDGE_SYMBOL(self) -> str:
        """Get the bridge coin symbol."""
        ...

    @property
    def SUPPORTED_COIN_LIST(self) -> List[str]:
        """Get the list of supported coin symbols."""
        ...

    @property
    def STRATEGY(self) -> str:
        """Get the name of the current trading strategy."""
        ...

    def get(self, key: str, default=None):
        """Get a config value by key (for dynamic keys)."""
        ...
